spec fn all_in_iff(a: &[i64], lo: i64, hi: i64, r: bool) -> bool {
    r == (forall|k: usize| k < a.len() ==> lo <= #[trigger] a[k] && a[k] <= hi)
}

spec fn prefix_iff(a: &[i64], lo: i64, hi: i64, n: usize, r: bool) -> bool {
    r == (forall|k: usize| k < n && k < a.len() ==> lo <= #[trigger] a[k] && a[k] <= hi)
}

spec fn idx_le(a: &[i64], i: usize) -> bool { i <= a.len() }

#[effects(pure)]
#[uses(all_in_iff, prefix_iff, idx_le)]
fn all_in_range(a: &[i64], lo: i64, hi: i64) -> (r: bool)
    ensures all_in_iff(a, lo, hi, r),
{
    let mut i: usize = 0;
    let mut ok: bool = true;
    while i < a.len()
        invariant idx_le(a, i), prefix_iff(a, lo, hi, i, ok),
        decreases a.len() - i,
    {
        if a[i] < lo || a[i] > hi {
            ok = false;
        }
        i = i + 1;
    }
    ok
}

