spec fn scan_inv(a: &[i64], v: i64, i: usize, r: usize) -> bool {
    i <= a.len()
    && ((r < i && a[r] == v && forall|j: usize| r < j && j < i ==> #[trigger] a[j] != v)
        || (r == a.len() && forall|j: usize| j < i ==> #[trigger] a[j] != v))
}

#[effects(pure)]
#[uses(in_bounds, last_if_found, none_if_len, scan_inv)]
fn find_last(a: &[i64], v: i64) -> (r: usize)
    ensures in_bounds(a, r), ensures last_if_found(a, v, r), ensures none_if_len(a, v, r),
{
    let mut i: usize = 0;
    let mut r: usize = a.len();
    while i < a.len()
        invariant scan_inv(a, v, i, r),
        decreases a.len() - i,
    {
        if a[i] == v {
            r = i;
        }
        i = i + 1;
    }
    r
}

