#[effects(pure)]
#[uses(digits_at_least_one, digits_at_most_succ, one_digit_iff_small)]
fn count_digits_iter(n: u64) -> (r: u64)
    ensures digits_at_least_one(r), digits_at_most_succ(n, r), one_digit_iff_small(n, r),
{
    let mut m: u64 = n;
    let mut c: u64 = 1;
    while m >= 10
        invariant c >= 1, m <= n, c + m <= n + 1, c == 1 ==> m == n, c > 1 ==> n >= 10,
        decreases m,
    {
        m = m / 10;
        c = c + 1;
    }
    c
}

spec fn tri_input(n: u64) -> bool { n <= 1000000 }

spec fn tri_result(n: u64, r: u64) -> bool { 2 * r == n * (n + 1) }

#[effects(pure)]
#[uses(tri_input, tri_result)]
fn triangle(n: u64) -> (r: u64)
    requires tri_input(n),
    ensures tri_result(n, r),
{
    let mut i: u64 = 0;
    let mut s: u64 = 0;
    while i < n
        invariant i <= n, n <= 1000000, 2 * s == i * (i + 1), s <= i * 1000000,
        decreases n - i,
    {
        i = i + 1;
        s = s + i;
    }
    s
}

