spec fn search_inv(a: &[i64], t: i64, lo: usize, hi: usize, res: usize) -> bool {
    lo <= hi && hi <= a.len() && res <= a.len() && hit(a, t, res)
        && (res == a.len() ==> below(a, t, lo) && above(a, t, hi))
}

#[effects(pure)]
#[uses(order::digits_bound, in_len, hit, absent, miss, below, above, search_inv)]
fn find_sorted(a: &[i64], t: i64) -> (r: usize)
    requires order::digits_bound(a),
    ensures in_len(a, r), hit(a, t, r), miss(a, t, r),
{
    let mut lo: usize = 0;
    let mut hi: usize = a.len();
    let mut res: usize = a.len();
    while lo < hi && res == a.len()
        invariant search_inv(a, t, lo, hi, res),
        decreases hi - lo,
    {
        let mid: usize = lo + (hi - lo) / 2;
        if a[mid] < t {
            lo = mid + 1;
        } else if a[mid] > t {
            hi = mid;
        } else {
            res = mid;
            hi = lo;
        }
    }
    res
}

