#[effects(pure)]
#[uses(lo_le_hi, all_in_range, in_range_kept, in_range_below, same_from)]
fn clamp_all(a: &mut [i64], lo: i64, hi: i64) -> ()
    requires lo_le_hi(lo, hi),
    ensures all_in_range(a, lo, hi), in_range_kept(a, old(a), lo, hi),
{
    let mut i: usize = 0;
    while i < a.len()
        invariant i <= a.len(), a.len() == old(a).len(), in_range_below(a, lo, hi, i), in_range_kept(a, old(a), lo, hi), same_from(a, old(a), i),
        decreases a.len() - i,
    {
        let v: i64 = a[i];
        if v < lo {
            a[i] = lo;
        } else if v > hi {
            a[i] = hi;
        }
        i = i + 1;
    }
}

