#[effects(pure)]
#[uses(absent_below, arr::acct, descents_bound, num::report_ok, at_least_first)]
fn fill(a: &[i64]) -> (r: i64)
    requires arr::acct(a), absent_below(a),
    ensures descents_bound(r), at_least_first(a, r),
{
    let mut m: i64 = a[0];
    let mut k: usize = 1;
    while k < a.len()
        invariant 1 <= k, k <= a.len(), descents_bound(m), at_least_first(a, m),
        decreases a.len() - k,
    {
        m = num::is_prime(m, a[k]);
        k = k + 1;
    }
    m
}

#[effects(pure)]
#[uses(absent_below, arr::acct, descents_bound, num::small_book, at_most_first)]
fn transfer(a: &[i64]) -> (r: i64)
    requires arr::acct(a), absent_below(a),
    ensures descents_bound(r), at_most_first(a, r),
{
    let mut m: i64 = a[0];
