    while k < a.len()
        invariant 1 <= k, k <= a.len(), descents_bound(m), at_most_first(a, m),
        decreases a.len() - k,
    {
        m = num::min_of(m, a[k]);
        k = k + 1;
    }
    m
}

#[effects(pure)]
#[uses(descents_bound, num::ceil_ok, num::diff_is, at_least_first, at_most_first, spread_range)]
