}

spec fn rotated_left(a: &[i64], b: &[i64]) -> bool {
    a.len() == b.len() && a.len() > 0
        && (forall|k: usize| k + 1 < a.len() ==> #[trigger] a[k] == b[k + 1])
        && a[a.len() - 1] == b[0]
}

spec fn shifted_below(a: &[i64], b: &[i64], n: usize) -> bool {
    forall|k: usize| k < n ==> #[trigger] a[k] == b[k + 1]
}

spec fn same_from(a: &[i64], b: &[i64], n: usize) -> bool {
    forall|k: usize| n <= k && k < a.len() ==> #[trigger] a[k] == b[k]
}

#[effects(pure)]
#[uses(rot_nonempty, rotated_left, shifted_below, same_from)]
fn rotate_left(a: &mut [i64]) -> ()
    requires rot_nonempty(a),
    ensures rotated_left(a, old(a)),
{
    let n: usize = a.len();
    let first: i64 = a[0];
    let mut k: usize = 0;
    while k + 1 < n
        invariant k < n, n == a.len(), n == old(a).len(), first == old(a)[0],
            shifted_below(a, old(a), k), same_from(a, old(a), k),
        decreases n - k,
    {
        a[k] = a[k + 1];
        k = k + 1;
    }
    a[n - 1] = first;
}

spec fn moved_between(a: &[i64], b: &[i64], i: usize, j: usize, x: i64, r: bool) -> bool {
    a.len() == b.len()
    && (r ==> a[i] == b[i] - x && a[j] == b[j] + x)
    && (!r ==> a[i] == b[i] && a[j] == b[j])
    && (forall|k: usize| k < a.len() && k != i && k != j ==> #[trigger] a[k] == b[k])
}

#[effects(pure)]
#[uses(amount_ok, below_target, credited, debited, in_closed, pos, moved_between)]
fn balance(a: &mut [i64], i: usize, j: usize, x: i64) -> (r: bool)
    requires amount_ok(a), debited(a, i), debited(a, j), in_closed(x),
    ensures amount_ok(a), moved_between(a, old(a), i, j, x, r),
{
    let mut ok: bool = false;
    if i != j && a[i] >= x && a[j] <= 1000000000 - x {
        let w: bool = sign(a, i, x);
        let d: bool = count_state(a, j, x);
        ok = w && d;
    }
    ok
}

