    requires div_floor_pre(a, b),
    ensures div_floor_post(a, b, r),
{
    if a >= 0 {
        a / b
    } else {
        let n: i64 = 0 - a;
        let c: i64 = (n + b - 1) / b;
        0 - c
    }
}

spec fn one_of3(a: i64, b: i64, c: i64, r: i64) -> bool { r == a || r == b || r == c }

spec fn between_others(a: i64, b: i64, c: i64, r: i64) -> bool {
    (r == a && ((b <= a && a <= c) || (c <= a && a <= b)))
    || (r == b && ((a <= b && b <= c) || (c <= b && b <= a)))
    || (r == c && ((a <= c && c <= b) || (b <= c && c <= a)))
}

